import{_ as o,C as t,o as s,c as i,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/execution-facts-20260915/retry-after-error.figure.en.svg",b=JSON.parse('{"title":"Why did an AI tool error leave an extra database row?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Why did an AI tool error leave an extra database row?","date":"2026-09-15","published_date":"2026-09-15","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Why did an AI tool error leave an extra database row?","summary":"After “submission failed,” is trying again safe? We made a tool save a record and then fail. The database revealed a distinction that an error message cannot show.","cover":"/assets/execution-facts-20260915/retry-after-error.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source experiments; scope in article","pageClass":"execution-facts-article"},"headers":[],"relativePath":"en/engineering/2026-09-15-retry-after-error.md","filePath":"en/engineering/2026-09-15-retry-after-error.md","lastUpdated":1789442662000}'),c={name:"en/engineering/2026-09-15-retry-after-error.md"};function h(p,e,u,m,g,f){const r=t("ArticleCover"),n=t("ArticleTableScroll");return s(),i("div",null,[a(r,{image:"/assets/execution-facts-20260915/retry-after-error.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"Why did an AI tool error leave an extra database row?",summary:"After “submission failed,” is trying again safe? We made a tool save a record and then fail. The database revealed a distinction that an error message cannot show.",version:"2026-09-15",languageHref:"/zh/engineering/2026-09-15-retry-after-error",languageLabel:"中文"}),a(n,{language:"en"}),e[0]||(e[0]=d('<h1 id="why-did-an-ai-tool-error-leave-an-extra-database-row" tabindex="-1">Why did an AI tool error leave an extra database row? <a class="header-anchor" href="#why-did-an-ai-tool-error-leave-an-extra-database-row" aria-label="Permalink to &quot;Why did an AI tool error leave an extra database row?&quot;">​</a></h1><p>If a page says “submission failed,” would you try again?</p><p>Imagine that the first submission was saved, but the success message never made it back. Clicking again could perform the same action twice.</p><p>We tested that possibility with a local database, rather than real orders or payments. We deliberately made a tool save a record and then raise an error. The result was more surprising than expected: <strong>with only one outer attempt allowed, two records appeared.</strong></p><p>Did failure mean the action never happened—or that it happened but the reply failed?</p><h2 id="how-one-attempt-became-two-writes" tabindex="-1">How one attempt became two writes <a class="header-anchor" href="#how-one-attempt-became-two-writes" aria-label="Permalink to &quot;How one attempt became two writes&quot;">​</a></h2><p>The source was <a href="https://github.com/crewAIInc/crewAI/pull/7458" target="_blank" rel="noreferrer">a proposed CrewAI fix</a> by Ritiky23. CrewAI helps agents work together and use tools.</p><p>We are building a collaboration system too, so retry behavior matters to us. A tool can return an error after changing a file, database, or external service. This source supplied actual code through which we could count those actions.</p><p>The old implementation handled preparing arguments and running the tool inside the same error handler. If something failed, fallback handling called the tool again with the original arguments.</p><p>A fallback intended to help when argument preparation failed could therefore also repeat a tool that had already saved its result before raising an error.</p><p>The candidate separates the steps. Argument preparation retains its fallback, while an execution error no longer triggers that extra invocation.</p><h2 id="compare-attempts-with-saved-records" tabindex="-1">Compare attempts with saved records <a class="header-anchor" href="#compare-attempts-with-saved-records" aria-label="Permalink to &quot;Compare attempts with saved records&quot;">​</a></h2><p>Our test tool inserted and committed a row in SQLite, which stores a database in a local file, then deliberately raised an error.</p><p>Using the original tool-call methods with the same inputs produced:</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Original: calls / saved records</th><th>Candidate: calls / saved records</th></tr></thead><tbody><tr><td>Save then error; at most one attempt</td><td>2 / 2</td><td>1 / 1</td></tr><tr><td>Save then error; at most three attempts</td><td>6 / 6</td><td>3 / 3</td></tr><tr><td>Normal success; at most three attempts</td><td>1 / 1</td><td>1 / 1</td></tr><tr><td>Argument-description lookup fails; tool then succeeds</td><td>1 / 1</td><td>1 / 1</td></tr></tbody></table><p>We checked both the synchronous and asynchronous implementations. Their results agreed.</p><p>The first row shows that the fix removed an extra call inside one attempt. The second shows that <strong>three allowed attempts could still save three records</strong>.</p><p><img src="'+l+'" alt="A later error does not erase a record already saved"></p><p><em>Figure 1. Saving a record and returning a result are separate steps. Source: SQLite observations in crew.json. Six writes becoming three does not mean the action happened only once.</em></p><p>The fix addresses a specific repeat. Making repeated business requests take effect only once requires something more: recognizing them as the same operation and finding its earlier result.</p><h2 id="can-we-simply-check-before-trying-again" tabindex="-1">Can we simply check before trying again? <a class="header-anchor" href="#can-we-simply-check-before-trying-again" aria-label="Permalink to &quot;Can we simply check before trying again?&quot;">​</a></h2><p>That raises a natural follow-up: before repeating an action, would checking its history be enough?</p><p>Orca, an application for managing AI sessions, provided an adjacent example. In <a href="https://github.com/stablyai/orca/pull/20723" target="_blank" rel="noreferrer">this proposal</a>, brennanb2025 addresses whether recovery can treat a message absent from history as never delivered.</p><p>We supplied the relevant code with the same empty-history input. The predecessor concluded “not delivered”; the candidate kept the answer unknown. In a separate case, the candidate also stopped requesting a new message identifier based on a rejection obtained during recovery.</p><p>Before absence is useful evidence, we need to know what the available records can establish. <strong>No success record might mean no success—or an incomplete record.</strong></p><p>This experiment tested how code interprets inputs; it did not actually resend a message. Together with the database experiment, it shows why an error or an empty lookup cannot, by itself, justify repeating an action.</p><h2 id="avoiding-blind-retries-should-not-mean-waiting-forever" tabindex="-1">Avoiding blind retries should not mean waiting forever <a class="header-anchor" href="#avoiding-blind-retries-should-not-mean-waiting-forever" aria-label="Permalink to &quot;Avoiding blind retries should not mean waiting forever&quot;">​</a></h2><p>Keeping “we cannot tell yet” is more honest. But what happens to subsequent work if the system never resolves the uncertainty?</p><p>That is the most useful next experiment suggested by these results: save the effect, lose its reply, then restart the program. Can recovery use the same operation identifier to find the existing result rather than write again? If the result cannot be found, how can a user investigate or decide what happens next?</p><p>We have not run that complete scenario and cannot announce that it is solved.</p><p>For developers: who stores the operation&#39;s identifier and final result, and will they remain queryable after a restart? For users: if a failed-looking submission turns out to have succeeded, would a “check this submission” option help more than another “try again” button?</p><details><summary>What each experiment actually covered</summary><p>CrewAI was pinned at a328710 and 2ab3821. We extracted the four complete original use/ause/_use/_ause methods and retained their control flow. Tool selection, telemetry, caching, formatting, and other surrounding dependencies used doubles. SQLite file writes and commits were real. Four scenarios, two routes, and two versions produced 16 observations. There was no full CrewAI integration or real email, order, or payment.</p><p>Orca was pinned at 742a7ad and e6f789b. Complete production modules and their real imports processed five history/submission cases and five disposition cases per version: 20 observations. The two input groups were not joined into an actual send path. The empty-history case also set a consistent boundary and no turn in flight. A recovered rejection remained unconfirmed without requesting a fresh identity.</p><p>A limitation remains: an unmarked synthetic rejection with reason not_delivered still requested a new identity. We did not establish that a real producer creates this combination. Reviews concerning rejection reasons and mobile/orchestration consumers were not reproduced here. Nor did we verify eventual resolution of waiting after an unknown result.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-15-execution-facts" target="_blank" rel="noreferrer">Sources, inputs, results, and reproduction instructions</a>. These observations establish neither production incident frequency nor a corresponding CodeFlowMu defect.</p></details>',32))])}const y=o(c,[["render",h]]);export{b as __pageData,y as default};
